(()=>{'use strict';
const panel=document.querySelector('#data-journey');if(!panel)return;
const examples=[
{source:'Hospital / HL7 v2 ADT',target:'EHR / FHIR Patient API',raw:'MSH|^~\\&|HIS|HOSPITAL|GRID|LOCAL|202609161200||ADT^A01|DEMO001|P|2.5\nPID|1||DEMO-1042^^^HOSPITAL^MR||EXAMPLE^ALEX||19890101',parsed:'Message type   ADT^A01\nPID-3.1        DEMO-1042\nPID-3.4        HOSPITAL\nPID-5.1        EXAMPLE\nPID-5.2        ALEX\nPID-7          19890101',map:'PID-3.1 → Patient.identifier.value\nPID-3.4 → configured identifier system\nPID-5.1 → Patient.name.family\nPID-5.2 → Patient.name.given\nPID-7   → Patient.birthDate',output:{resourceType:'Patient',identifier:[{system:'https://example.org/hospital/mrn',value:'DEMO-1042'}],name:[{family:'EXAMPLE',given:['ALEX']}],birthDate:'1989-01-01'},checks:'Required identifier: present\nIdentifier authority: mapped\nBirth date: converted to YYYY-MM-DD\nDestination profile: validate before delivery'},
{source:'Laboratory / HL7 v2 ORU',target:'Clinical system / FHIR Observation API',raw:'MSH|^~\\&|LIS|LAB|GRID|LOCAL|202609161200||ORU^R01|DEMO002|P|2.5\nPID|1||DEMO-1042^^^HOSPITAL^MR\nOBX|1|NM|2345-7^Glucose^LN||5.4|mmol/L|||||F',parsed:'OBX-2          NM (numeric)\nOBX-3.1        2345-7\nOBX-3.2        Glucose\nOBX-5          5.4\nOBX-6          mmol/L\nOBX-11         F',map:'OBX-3 → Observation.code\nOBX-5 → valueQuantity.value (number)\nOBX-6 → valueQuantity.unit\nOBX-11 F → status: final\nPID-3 → resolved patient reference',output:{resourceType:'Observation',status:'final',code:{coding:[{system:'http://loinc.org',code:'2345-7',display:'Glucose'}]},subject:{reference:'Patient/DEMO-1042'},valueQuantity:{value:5.4,unit:'mmol/L'}},checks:'Result value: numeric\nUnits: present\nResult status: mapped\nPatient reference: resolve before delivery'},
{source:'Medical device / JSON API',target:'Care application / normalized JSON API',raw:'{\n  "device_id": "DEMO-SENSOR-01",\n  "patient_id": "DEMO-1042",\n  "glucose": "5.4",\n  "unit": "mmol/L",\n  "time": "2026-09-16T12:00:00Z"\n}',parsed:'device_id    DEMO-SENSOR-01\npatient_id   DEMO-1042\nglucose      "5.4" (string)\nunit         mmol/L\ntime         UTC timestamp',map:'patient_id → patientId\ndevice_id  → source.deviceId\nglucose    → value (number)\nunit       → unit\ntime       → observedAt',output:{patientId:'DEMO-1042',source:{deviceId:'DEMO-SENSOR-01'},type:'glucose',value:5.4,unit:'mmol/L',observedAt:'2026-09-16T12:00:00Z'},checks:'Patient identifier: present\nValue: converted to number\nUnit: matches configured contract\nTimestamp: valid UTC format'},
{source:'Patient administration / CSV file',target:'Downstream application / JSON API',raw:'patient_id,family_name,given_name,dob\nDEMO-1042,Example,Alex,1989-01-01',parsed:'Row 1\npatient_id    DEMO-1042\nfamily_name   Example\ngiven_name    Alex\ndob           1989-01-01',map:'patient_id  → id\nfamily_name → name.family\ngiven_name  → name.given\ndob         → birthDate\nCSV row     → JSON object',output:{id:'DEMO-1042',name:{family:'Example',given:'Alex'},birthDate:'1989-01-01'},checks:'Required columns: present\nIdentifier: non-empty\nDate: valid YYYY-MM-DD\nDestination schema: validate before delivery'}
];
const stages=['Receive','Parse','Transform','Validate','Route'];let example=0,stage=0,playing=false,elapsed=0,last=0;
const $=id=>document.getElementById(id),play=$('flow-play');
function render(){const e=examples[example];document.querySelectorAll('[data-example]').forEach(b=>b.setAttribute('aria-pressed',String(+b.dataset.example===example)));document.querySelectorAll('[data-flow-stage]').forEach(b=>b.setAttribute('aria-pressed',String(+b.dataset.flowStage===stage)));$('flow-label').textContent=`0${stage+1} / ${stages[stage].toUpperCase()}`;$('flow-title').textContent=['Receive the original payload.','Make the structure readable.','Map to the destination model.','Check before sending.','Deliver where it is needed.'][stage];$('flow-description').textContent=['Accept data using the source connection configured in your workflow.','Identify segments, columns or object fields so each value can be addressed.','Apply your field mappings, data types and formatting rules.','Apply configured schema and business rules. Route failures to your chosen review or error-handling path.','Use configured routing rules and destination connections to send the transformed payload.'][stage];$('flow-destination').textContent=`${e.source} → ${e.target}`;$('flow-code-label').textContent=['SOURCE PAYLOAD','PARSED FIELDS','TRANSFORMATION RULES','EXAMPLE CHECKS','TRANSFORMED OUTPUT'][stage];$('flow-code').textContent=[e.raw,e.parsed,e.map,e.checks,JSON.stringify(e.output,null,2)][stage];panel.style.setProperty('--flow-progress',`${(stage+1)*20}%`);play.textContent=playing?'Pause walkthrough Ⅱ':'Play walkthrough →';play.setAttribute('aria-pressed',String(playing));}
document.querySelector('.flow-toggle').addEventListener('click',e=>{const open=panel.hidden;panel.hidden=!open;e.currentTarget.setAttribute('aria-expanded',String(open));e.currentTarget.textContent=open?'Close the data journey −':'Explore the data journey +';if(open){render();panel.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});}else{playing=false;render();}});
document.querySelectorAll('[data-example]').forEach(b=>b.addEventListener('click',()=>{example=+b.dataset.example;stage=0;elapsed=0;render();}));document.querySelectorAll('[data-flow-stage]').forEach(b=>b.addEventListener('click',()=>{stage=+b.dataset.flowStage;elapsed=0;playing=false;render();}));play.addEventListener('click',()=>{playing=!playing;elapsed=0;render();});document.querySelectorAll('.global-motion').forEach(b=>b.addEventListener('click',()=>{playing=false;render();}));matchMedia('(prefers-reduced-motion: reduce)').addEventListener('change',()=>{playing=false;render();});
function tick(now){const dt=Math.min(now-last,100);last=now;if(playing&&!panel.hidden&&!document.hidden){elapsed+=dt;if(elapsed>=4000){elapsed=0;stage=(stage+1)%5;if(stage===0)example=(example+1)%examples.length;render();}}requestAnimationFrame(tick);}render();requestAnimationFrame(tick);
})();
